import Model from 'flarum/common/Model';
export default class UserMoneyHistory extends Model {
  balanceDelta = Model.attribute('balanceDelta');
  source = Model.attribute('source');
  sourceKey = Model.attribute('sourceKey');
  sourceParams = Model.attribute('sourceParams');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  balanceBefore = Model.attribute('balanceBefore');
  balanceAfter = Model.attribute('balanceAfter');
  user = Model.hasOne('user');
  actor = Model.hasOne('actor');
}
flarum.reg.add('huoxin-money-with-history', 'forum/models/UserMoneyHistory', UserMoneyHistory);